def forward(groups):
    try:
        value, unit = float(groups[1]), groups[2]
        scale = {'B': 1, 'KB': 1024, 'GB': 1024 ** 3}
        canonical_value = int(round(value * scale[unit]))
        return {'stored': [canonical_value], 'layout': [unit]}
    except (ValueError, KeyError):
        raise ValueError("Invalid input for size_with_units")

def inverse(record):
    canonical_value, unit = record['stored'][0], record['layout'][0]
    scale = {'B': 1, 'KB': 1024, 'GB': 1024 ** 3}
    value = canonical_value / scale[unit]
    return f"size: {value:.1f} {unit}"
